        "ios.solve.prompt.solve": "Löse die Aufgabe aus dem angehängten Dokument Schritt für Schritt, wie ein Nachhilfelehrer: Ich will die Methode verstehen, nicht nur das Ergebnis. Wenn es mehrere Fragen gibt, bearbeite nur die erste.\nSchreib deine Antwort genau in dieser Form und lass die Markierungen auf Englisch:\n[SUBJECT] math, physics, biology oder other\n[STEP] ein kurzer Titel\nEin bis drei Sätze, die den Schritt erklären.\n(2 bis 5 Markierungen [STEP])\n[ANSWER] das Endergebnis, kurz\nSchreib Formeln in einfachem LaTeX zwischen $, und setz eine wichtige Formel allein in eine eigene Zeile zwischen $$.",
