    /// **L'anglais, au complet.**
    ///
    /// Elle l'est enfin : la table ne portait que les clés écrites depuis qu'on s'était
    /// aperçu qu'un anglophone lisait le parcours en français, et tout le reste retombait
    /// sur le catalogue partagé puis sur le français. Un lecteur anglophone traversait donc
    /// l'app en deux langues, sans jamais avoir demandé la seconde. Elle porte maintenant
    /// **toutes les clés du français**, dans le même ordre et sous les mêmes commentaires —
    /// et le test de parité (`testIosCatalogsHaveTheSameKeys`) le garde ainsi.
